  name: 'setup',
  invoke: 'fgos setup',
  description: 'Legacy compatibility command: insert the fgos shell-integration source line into detected shell rc file(s), ensure shared config defaults, wire support hooks, and run registered fixes. Target workspace onboarding is fgctl init (it needs --from <source> when .fgos/distribution.json is absent), then local fgos doctor --fix and fgos doctor; doctor --fix runs only the registered fixes, so run fgos setup once in the project for the config defaults, git hook and Claude Code hook it does not write. Shell/global setup compatibility stays here until a compatibility-window decision retires it.',
  parameters: {
    type: 'object',
    properties: {
      pretty: { type: 'boolean', description: 'Render colored human-readable text instead of the JSON envelope.' },
    },
    required: [],
  },
  examples: ['fgos setup', 'fgos setup --pretty'],
  touchesState: true,
  requiresExistingStore: false,
  externalEffect: false,
  paginated: false,
  deprecated: 'since 2026-09-14; target workspace onboarding starts with fgctl init (plain fgctl init downloads the latest release when .fgos/distribution.json is absent), then .fgos/installation/bin/fgos doctor --fix and .fgos/installation/bin/fgos doctor; doctor --fix runs only the registered fixes, so run fgos setup once in the project for the config defaults, git hook and Claude Code hook it does not write; shell/global integration stays here until a compatibility-window decision retires it',
},
{
  name: 'uninstall',
  invoke: 'fgos uninstall',
  description: 'Reverse fgos setup\'s own wiring: unwire core.hooksPath/.githooks (fill-only — only when still exactly .githooks, mirroring installGitHooks) and report (never delete) any fgos shell-rc source line found, since deletion stays a human act. Never touches .fgos/ data or config. Requires --yes; refuses with no side effects otherwise. --remove-package additionally shells out to "npm uninstall -g forgent" (npm global installs only, Linux/macOS only — an unproven spike, tsk-4iv-2); omitted, behavior is unchanged from wiring-only.',
  parameters: {
    type: 'object',
    properties: {
      pretty: { type: 'boolean', description: 'Render colored human-readable text instead of the JSON envelope.' },
      yes: { type: 'boolean', description: 'Confirm the destructive steps (unwiring git hooks, and package removal if --remove-package is also given). Required — omitting it refuses before touching anything.' },
      'remove-package': { type: 'boolean', description: 'Also attempt "npm uninstall -g forgent" after the wiring reversal. npm global installs only, Linux/macOS only (tsk-4iv-2 spike scope) — omit to keep the wiring-only default.' },
    },
    required: [],
  },
  examples: ['fgos uninstall --yes', 'fgos uninstall --yes --remove-package', 'fgos uninstall --yes --pretty'],
  touchesState: true,
  requiresExistingStore: false,
  externalEffect: false,
  paginated: false,
  deprecated: null,
},
{
  name: 'doctor',
  invoke: 'fgos doctor',
  description: 'Diagnostic by default (Node/git availability, whether the shell-integration source line is present in detected rc file(s), and whether the shared config file is not stale relative to every registered default). --fix runs every registered fix (docs/history/doctor-fix-gate-bypass/CONTEXT.md D2/D3) before re-reporting checks -- a deliberate reversal of RUL9/RUL11 (docs/specs/distribution.md); without --fix, behavior is unchanged and writes nothing. Exits 0 whatever the checks say (fgctl init/upgrade/repair run it as their tail and treat a non-zero exit as a degraded install); pass --strict to exit 1 when any check still fails.',
  parameters: {
    type: 'object',
    properties: {
      pretty: { type: 'boolean', description: 'Render colored human-readable text instead of the JSON envelope.' },
      fix: { type: 'boolean', description: 'Run every registered fix against the current cwd before reporting checks. Omit to keep doctor read-only (default, unchanged behavior).' },
      strict: { type: 'boolean', description: 'Exit 1 when any check fails (after the fixes ran, with --fix). Omit to keep the default exit 0 whatever the checks say.' },
    },
    required: [],
  },
  examples: ['fgos doctor', 'fgos doctor --pretty', 'fgos doctor --fix', 'fgos doctor --strict'],
  touchesState: true,
  requiresExistingStore: false,
  externalEffect: false,
  paginated: false,
  deprecated: null,
},
{
  name: 'unclaim',
